EXPECTED_DEFAULT_DB = 'IPTHData_Dev'
SNAPSHOT_RE = re.compile(r'WITH\s*\(\s*SNAPSHOT\s*\)', re.I)
BACKUP_BASE = Path.home() / '.ipth_mes_updater_backups' / VERSION


class Reject(RuntimeError):
    pass


def digest(data: bytes) -> str:
    return hashlib.sha256(data).hexdigest()


def repo_roots() -> tuple[Path, Path]:
    be = Path.cwd().resolve()
    fe = be.parent / 'Interplex_MES_FE'
    if be.name != 'Interplex_MES_BE' or not (be / 'app').is_dir() or not fe.is_dir():
        raise Reject('Run from Interplex_MES_BE; sibling Interplex_MES_FE required.')
    return be, fe.resolve()


def payload_data():
    encoded = ''.join(PAYLOAD_B85.split())
    data = base64.b85decode(encoded)
    if digest(data) != PAYLOAD_SHA256:
        raise Reject('Embedded updater payload checksum mismatch.')
    z = zipfile.ZipFile(io.BytesIO(data))
    if z.testzip():
        raise Reject('Embedded ZIP corrupt.')
    m = json.loads(z.read('MANIFEST.json'))
    names = list(m['baseline'])
    if len(names) != 12 or len(m['docs']) != 2:
        raise Reject('Unrecognized embedded patch manifest.')
    for rel in names:
        if digest(z.read('BE/'+rel)) != m['after'][rel]:
            raise Reject('Patched source checksum mismatch: '+rel)
        ast.parse(z.read('BE/'+rel).decode('utf8'), filename=rel)
    for rel,h in m['docs'].items():
        if digest(z.read('FE/'+rel)) != h:
            raise Reject('Document checksum mismatch: '+rel)
    return m, z


def safe_file(root: Path, relative: str) -> Path:
    rel=Path(relative)
    if rel.is_absolute() or '..' in rel.parts or not rel.parts:
        raise Reject('Unsafe updater path: '+relative)
    # Never follow an existing symlink in any component, including the file itself.
    p=root
    for part in rel.parts:
        p=p / part
        if p.is_symlink():
            raise Reject('Refusing symlink path: '+str(p))
    if p.exists() and not p.is_file():
        raise Reject('Expected file, found non-file: '+str(p))
    return p


def inventory(be: Path, fe: Path, m: dict) -> tuple[str, list]:
    statuses=[]
    for rel,h in m['dependencies'].items():
        p=safe_file(be,rel)
        actual=digest(p.read_bytes()) if p.is_file() else 'MISSING'
        if actual!=h:
            raise Reject(f'Dependency modified/absent: {rel}; actual={actual}, expected={h}')
    for rel,h in m['baseline'].items():
        p=safe_file(be,rel)
        actual=digest(p.read_bytes()) if p.is_file() else 'MISSING'
        status='BEFORE' if actual==h else ('AFTER' if actual==m['after'][rel] else 'UNKNOWN')
        statuses.append(('BE',rel,status,actual))
    for rel,h in m['docs'].items():
        p=safe_file(fe,rel)
        actual=digest(p.read_bytes()) if p.is_file() else 'ABSENT'
        status='BEFORE' if actual=='ABSENT' else ('AFTER' if actual==h else 'UNKNOWN')
        statuses.append(('FE',rel,status,actual))
    if any(row[2]=='UNKNOWN' for row in statuses):
        bad=[(item[0],item[1],item[3]) for item in statuses if item[2]=='UNKNOWN']
        raise Reject('Unknown source/docs SHA-256; refusing overwrite:\n'+json.dumps(bad,ensure_ascii=False,indent=2))
    # Refuse uncollected runtime Python hints, including newly added modules.
    unexpected=[]
    selected=set(m['baseline'])
    for p in (be/'app').rglob('*.py'):
        rel=p.relative_to(be).as_posix()
        if any(d in ('__pycache__','.venv','.git') for d in p.parts):
            continue
        if p.is_symlink():
            raise Reject('Unexpected symlink in runtime Python tree: '+str(p))
        if rel in selected:
            continue
        if SNAPSHOT_RE.search(p.read_text('utf8')):
            unexpected.append(rel)
    if unexpected:
        raise Reject('Additional runtime SNAPSHOT usage not covered by baseline:\n  '+'\n  '.join(unexpected))
    unique={row[2] for row in statuses}
    return ('BEFORE' if unique=={'BEFORE'} else ('AFTER' if unique=={'AFTER'} else 'MIXED')),statuses


def _print_git_status(be: Path, fe: Path) -> None:
    import subprocess
    for label,path in (('BE',be),('FE',fe)):
        try:
            result=subprocess.run(['git','-C',str(path),'branch','--show-current'],capture_output=True,text=True,timeout=8)
            print(f'[GIT] {label} branch: {result.stdout.strip() or "unknown"}')
        except Exception:
            print(f'[GIT] {label} branch: unavailable')


def check_db(expected_db: str) -> None:
    """Read-only validation against the SAME SQLAlchemy engine as runtime MES."""
    # Script lives under sibling FE while CWD is BE; Python does not always add
    # the working directory to sys.path when running a script by filename.
    backend_dir = str(Path.cwd().resolve())
    if backend_dir not in sys.path:
        sys.path.insert(0, backend_dir)
    from sqlalchemy import text
    from app.db.session import engine
    query=text('''
      SELECT DB_NAME() AS DatabaseName, s.name AS SchemaName, t.name AS TableName,
             CAST(t.is_memory_optimized AS int) AS IsMemoryOptimized
      FROM sys.tables t JOIN sys.schemas s ON s.schema_id=t.schema_id
      WHERE s.name='dbo' AND t.name IN ('Master_WO_Log', 'Master_WO_Message')
    ''')
    with engine.connect() as conn:
        rows=[dict(r) for r in conn.execute(query).mappings().all()]
    name_set={r['DatabaseName'] for r in rows}
    if name_set != {expected_db}:
        raise Reject(f'DB guard: expected {expected_db!r}; actual database(s) {name_set!r}.')
    by_name={r['TableName']:r for r in rows}
    if set(by_name)!={'Master_WO_Log','Master_WO_Message'}:
        raise Reject(f'DB guard: required dbo tables missing: {sorted(set(("Master_WO_Log","Master_WO_Message"))-set(by_name))}')
    for table,row in sorted(by_name.items()):
        if int(row['IsMemoryOptimized'])!=0:
            raise Reject('DB guard: still MEMORY_OPTIMIZED: dbo.'+table)
        print(f'[DB PASS] {expected_db} / dbo.{table} = DISK_BASED')
    print('[DB] Read-only storage check PASS; this does not validate all business transactions.')


def atomic_write(path: Path, raw: bytes) -> None:
    path.parent.mkdir(parents=True,exist_ok=True)
    fd, tmp=tempfile.mkstemp(prefix='.ipth_diskbased_',suffix='.tmp',dir=str(path.parent))
    try:
        with os.fdopen(fd,'wb') as f:
            f.write(raw)
            f.flush();os.fsync(f.fileno())
        if path.is_file():
            os.chmod(tmp,path.stat().st_mode & 0o777)
        os.replace(tmp,path)
    finally:
        if os.path.exists(tmp):os.unlink(tmp)


def apply(be: Path, fe: Path, m: dict, z, db_name: str) -> None:
    status,rows=inventory(be,fe,m)
    if status=='AFTER':
        print('ALREADY APPLIED: no files changed.')
        return
    if status!='BEFORE':
        raise Reject('Mixed before/after state: refuse apply; inspect files or rollback manually.')
    # Run the database precondition before writing or creating backup files.
    check_db(db_name)
    stamp=dt.datetime.now(dt.timezone.utc).strftime('%Y%m%dT%H%M%S%fZ')
    backup=BACKUP_BASE/stamp
    backup.mkdir(parents=True,exist_ok=False)
    entries=[]
    for label,rel,_,_ in rows:
        root=be if label=='BE' else fe
        path=safe_file(root,rel)
        raw=path.read_bytes() if path.is_file() else None
        if label=='BE' and raw is None:
            raise Reject('Missing source at backup time: '+rel)
        if raw is not None:
            bp=backup/label/rel
            bp.parent.mkdir(parents=True,exist_ok=True)
            bp.write_bytes(raw)
        entries.append({'root':label,'rel':rel,'before':digest(raw) if raw is not None else None,
                        'after':m['after'][rel] if label=='BE' else m['docs'][rel]})
    bmf={'version':VERSION,'timestamp':stamp,'be_root':str(be),'fe_root':str(fe),
         'expected_db':db_name,'entries':entries,'committed':False}
    (backup/'backup_manifest.json').write_text(json.dumps(bmf,indent=2),encoding='utf8')
    changed=[]
    try:
        # Re-check all baseline sources immediately before installation.
        state,_=inventory(be,fe,m)
        if state!='BEFORE':raise Reject('Source state changed while preparing backups.')
        for entry in entries:
            label,rel=entry['root'],entry['rel']
            root=be if label=='BE' else fe
            new=z.read(label+'/'+rel)
            p=safe_file(root,rel)
            atomic_write(p,new)
            changed.append(entry)
            print(f'[APPLIED] {label}/{rel}')
        state,_=inventory(be,fe,m)
        if state!='AFTER':raise Reject('Post-apply verification failed.')
        bmf['committed']=True
        (backup/'backup_manifest.json').write_text(json.dumps(bmf,indent=2),encoding='utf8')
        print(f'VERDICT: PASS — source/docs applied and SHA-256 verified; backup={backup}')
    except BaseException:
        print('[RECOVERY] Apply failure: restoring source from this run backup.')
        for entry in reversed(changed):
            label,rel=entry['root'],entry['rel']
            root=be if label=='BE' else fe
            p=safe_file(root,rel)
            before=entry['before']
            if before is None:
                if p.exists():p.unlink()
            else:
                raw=(backup/label/rel).read_bytes()
                if digest(raw)!=before:raise Reject('Backup corrupt; manual restoration required: '+rel)
                atomic_write(p,raw)
        raise


def rollback(be: Path,fe: Path) -> None:
    files=sorted(BACKUP_BASE.glob('*/backup_manifest.json'),reverse=True)
    if not files:
        raise Reject('No rollback backup found.')
    f=files[0];saved=json.loads(f.read_text('utf8'))
    if not saved.get('committed'):
        raise Reject('Latest backup is from an incomplete APPLY; review it manually: '+str(f))
    if saved.get('be_root')!=str(be) or saved.get('fe_root')!=str(fe):
        raise Reject('Backup root mismatch; refusing rollback: '+str(f))
    entries=saved['entries']
    # Strictly refuse rollback if ANY updated file was changed by the user since apply.
    for e in entries:
        root=be if e['root']=='BE' else fe
        p=safe_file(root,e['rel'])
        actual=digest(p.read_bytes()) if p.is_file() else None
        if actual!=e['after']:
            raise Reject(f'Rollback blocked by changed file {e["root"]}/{e["rel"]}: actual={actual}')
        if e['before'] is not None:
            bp=f.parent/e['root']/e['rel']
            if not bp.is_file() or digest(bp.read_bytes())!=e['before']:
                raise Reject('Rollback backup missing or corrupt: '+str(bp))
    for e in reversed(entries):
        root=be if e['root']=='BE' else fe
        p=safe_file(root,e['rel'])
        if e['before'] is None:
            p.unlink()
        else:
            atomic_write(p,(f.parent/e['root']/e['rel']).read_bytes())
        print(f'[RESTORED] {e["root"]}/{e["rel"]}')
    f.rename(f.with_name('backup_manifest.rolled_back.json'))
    print('ROLLED BACK: source/docs only. WARNING: if DB tables are still Disk-Based, the old code may fail.')


def main():
    p=argparse.ArgumentParser(description='Source-first MES disk-based SQL hint compatibility updater')
    group=p.add_mutually_exclusive_group(required=True)
    for opt in ('scan','check-db','apply','verify','rollback'):
        group.add_argument('--'+opt,action='store_true')
    p.add_argument('--expected-db',default=EXPECTED_DEFAULT_DB,help='Default IPTHData_Dev, must match actual SQLAlchemy connection')
    args=p.parse_args()
    try:
        be,fe=repo_roots()
        print('===',VERSION,'===')
        print('BE:',be,'\nFE:',fe)
        if args.check_db:
            check_db(args.expected_db)
            print('VERDICT: PASS — database storage guard (read-only)')
            return 0
        if args.rollback:
            rollback(be,fe)
            return 0
        m,z=payload_data()
        if args.apply:
            apply(be,fe,m,z,args.expected_db)
            return 0
        state,rows=inventory(be,fe,m)
        _print_git_status(be,fe)
        for label,rel,status,h in rows:
            print(f'[{status}] {label}/{rel} SHA256={h}')
        if args.verify:
            if state!='AFTER':
                raise Reject('Verify requires all files at AFTER hashes; state='+state)
            print('VERDICT: PASS — installed Backend Python / Markdown match expected SHA-256')
        elif state=='BEFORE':
            print('VERDICT: PASS — ready for code/docs APPLY; run --check-db first. No changes made.')
        elif state=='AFTER':
            print('VERDICT: PASS — ALREADY APPLIED (no changes needed)')
        else:
            raise Reject('Mixed before/after state. No changes made.')
        return 0
    except Reject as exc:
        print('VERDICT: REJECT —',str(exc),file=sys.stderr)
        return 2
    except Exception as exc:
        print(f'VERDICT: REJECT — unexpected {type(exc).__name__}: {exc}',file=sys.stderr)
        return 3


if __name__=='__main__':
    sys.exit(main())
